def _write_csv(db, table, path, project=None):
    """写一个表的 CSV(project 为 None 时导出全部项目)。返回导出条数"""
    import csv
    headers, mapper = EXPORT_SPECS[table]
    if project is None:
        rows = db.execute(f"SELECT * FROM {table} ORDER BY id").fetchall()
    else:
        rows = db.execute(f"SELECT * FROM {table} WHERE project=? ORDER BY id", (project,)).fetchall()
    with open(path, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f)
        w.writerow(headers)
        for r in rows:
            w.writerow(mapper(r))
    return len(rows)


def cmd_export(db, a):
    table = a.sub
    if table not in EXPORT_SPECS:
        sys.exit(f"错误: 未知表 {table}, 可选: {', '.join(EXPORT_SPECS)}")
    n = _write_csv(db, table, a.out, getattr(a, "project", None))
    scope = f"项目「{a.project}」的 " if getattr(a, "project", None) else ""
    print(f"[OK] 已导出 {scope}{n} 条记录 → {os.path.abspath(a.out)} (UTF-8 BOM, Excel 可直接打开)")


def cmd_export_all(db, a):
    """导出全部台账: 三张总表 + 按项目分表"""
    outdir = a.out
    os.makedirs(outdir, exist_ok=True)
    subdir = os.path.join(outdir, "按项目")
    os.makedirs(subdir, exist_ok=True)
    for table, fname in (("progress", "01-工程进度.csv"), ("materials", "02-材料出入库.csv"),
                         ("hazards", "03-安全隐患.csv")):
        _write_csv(db, table, os.path.join(outdir, fname))
    projs = set()
    for t in EXPORT_SPECS:
        for r in db.execute(f"SELECT DISTINCT project FROM {t}").fetchall():
            projs.add(r["project"])
    for proj in sorted(projs):
        safe = proj.replace("/", "_").replace("\\", "_").replace(os.sep, "_").strip() or "未命名项目"
        for table, fname in (("progress", "进度.csv"), ("materials", "材料.csv"), ("hazards", "隐患.csv")):
            _write_csv(db, table, os.path.join(subdir, f"{safe}-{fname}"), proj)
    print(f"[OK] 已导出全部台账到: {os.path.abspath(outdir)}")
    print(f"     总表 3 个文件 + 按项目 {len(projs)} 个项目 × 3 张分表 = {3 + len(projs) * 3} 个 CSV")


